-- Options screen (generated by _shared/tdlib/options_gen.py).
-- Values are stored in savegame.mod.* and read by main.lua.

local PANEL_W = 820
local ROW_H = 44
local SLIDER_W = 260

local function ru() return GetInt("options.language") == 7 end
local function tr(pair) if ru() then return pair[2] end return pair[1] end

local TITLE = { "Camera Drone", "Дрон с камерой" }
local SUBTITLE = { "Fly, look, drop", "Летай, смотри, сбрасывай" }
local ROWS = {
	{ kind = "slider", key = "speed", label = { "Max speed", "Макс. скорость" }, default = 12.0, min = 5, max = 25, fmt = { "%.0f m/s", "%.0f м/с" }, int = false, step = 1 },
	{ kind = "slider", key = "range", label = { "Signal range", "Дальность связи" }, default = 150.0, min = 50, max = 500, fmt = { "%.0f m", "%.0f м" }, int = false, step = 10 },
	{ kind = "choice", key = "battery", label = { "Battery", "Батарея" }, default = true, choices = { { true, "Limited", "Ограничена" }, { false, "Unlimited", "Без ограничений" } } },
	{ kind = "slider", key = "minutes", label = { "Battery lasts", "Батареи хватает на" }, default = 3.0, min = 1, max = 10, fmt = { "%.0f min", "%.0f мин" }, int = false, step = 1 },
	{ kind = "slider", key = "bombs", label = { "Bombs per flight", "Бомб за полёт" }, default = 3.0, min = 1, max = 10, fmt = { "%.0f", "%.0f" }, int = false, step = 1 },
	{ kind = "choice", key = "grenade", label = { "Drop Singularity Grenade", "Сбрасывать грав. гранату" }, default = true, choices = { { true, "If that mod is on", "Если тот мод включён" }, { false, "No, own bomb", "Нет, своя бомба" } } },
	{ kind = "slider", key = "bombsize", label = { "Own bomb size", "Сила своей бомбы" }, default = 1.0, min = 0.5, max = 2.0, fmt = { "%.1f", "%.1f" }, int = false, step = 0.1 },
	{ kind = "slider", key = "crash", label = { "Breaks at impact of", "Ломается при ударе" }, default = 9.0, min = 4, max = 20, fmt = { "%.0f m/s", "%.0f м/с" }, int = false, step = 1 },
	{ kind = "slider", key = "sens", label = { "Mouse sensitivity", "Чувствительность мыши" }, default = 1.0, min = 0.2, max = 3, fmt = { "x%.1f", "x%.1f" }, int = false, step = 0.1 },
	{ kind = "slider", key = "fov", label = { "Camera FOV", "Угол обзора камеры" }, default = 90.0, min = 60, max = 110, fmt = { "%.0f°", "%.0f°" }, int = false, step = 5 },
	{ kind = "choice", key = "freeze", label = { "Freeze player while flying", "Тело игрока стоит" }, default = true, choices = { { true, "Yes", "Да" }, { false, "No", "Нет" } } },
}

local function key(r) return "savegame.mod." .. r.key end

local function getValue(r)
	local k = key(r)
	if not HasKey(k) then return r.default end
	local t = type(r.default)
	if t == "boolean" then return GetBool(k) end
	if t == "string" then return GetString(k) end
	if r.int then return GetInt(k) end
	return GetFloat(k)
end

local function setValue(r, v)
	local k = key(r)
	local t = type(r.default)
	if t == "boolean" then SetBool(k, v)
	elseif t == "string" then SetString(k, v)
	elseif r.int then SetInt(k, v)
	else SetFloat(k, v) end
end

local function resetDefaults()
	for i = 1, #ROWS do setValue(ROWS[i], ROWS[i].default) end
end

local function sliderRow(r)
	local value = getValue(r)
	UiPush()
		UiAlign("left middle")
		UiFont("regular.ttf", 24)
		UiColor(1, 1, 1, 0.9)
		UiText(tr(r.label))
		UiTranslate(330, 0)
		UiColor(1, 1, 1, 0.25)
		UiRect(SLIDER_W, 4)
		local t = (value - r.min) / (r.max - r.min)
		if t < 0 then t = 0 elseif t > 1 then t = 1 end
		UiColor(0.4, 0.9, 0.5, 1)
		UiRect(SLIDER_W * t, 4)
		UiColor(1, 1, 1, 1)
		UiTranslate(-10, 0)
		local pos = UiSlider("MOD/ui/dot.png", "x", SLIDER_W * t, 0, SLIDER_W)
		local nv = r.min + (pos / SLIDER_W) * (r.max - r.min)
		local step = r.step or 0.1
		nv = math.floor(nv / step + 0.5) * step
		if r.int then nv = math.floor(nv + 0.5) end
		if math.abs(nv - value) > 1e-6 then setValue(r, nv) end
		UiTranslate(SLIDER_W + 40, 0)
		UiFont("bold.ttf", 24)
		UiText(string.format(tr(r.fmt), getValue(r)))
	UiPop()
end

local function choiceRow(r)
	local current = getValue(r)
	local idx = 1
	for i = 1, #r.choices do if r.choices[i][1] == current then idx = i end end
	UiPush()
		UiAlign("left middle")
		UiFont("regular.ttf", 24)
		UiColor(1, 1, 1, 0.9)
		UiText(tr(r.label))
		UiTranslate(330, 0)
		UiFont("bold.ttf", 24)
		UiColor(1, 1, 1, 1)
		UiButtonImageBox("ui/common/box-outline-6.png", 6, 6, 1, 1, 1, 0.6)
		UiButtonHoverColor(0.4, 0.9, 0.5, 1)
		local c = r.choices[idx]
		local label = c[2]
		if ru() then label = c[3] end
		if UiTextButton(label, 340, 36) then
			setValue(r, r.choices[(idx % #r.choices) + 1][1])
		end
	UiPop()
end

function draw()
	local h = 190 + #ROWS * ROW_H
	UiPush()
		UiColor(0, 0, 0, 0.55)
		UiRect(UiWidth(), UiHeight())
	UiPop()
	UiPush()
		UiTranslate(UiCenter(), UiMiddle())
		UiAlign("center middle")
		UiColor(0.06, 0.06, 0.08, 0.93)
		UiRoundedRect(PANEL_W, h, 14)
		UiColor(0.4, 0.9, 0.5, 0.8)
		UiRoundedRectOutline(PANEL_W, h, 14, 2)
		UiTranslate(0, -h / 2 + 46)
		UiFont("bold.ttf", 40)
		UiColor(1, 1, 1, 1)
		UiText(tr(TITLE))
		UiTranslate(0, 34)
		UiFont("regular.ttf", 20)
		UiColor(0.4, 0.9, 0.5, 0.8)
		UiText(tr(SUBTITLE))
		UiTranslate(-PANEL_W / 2 + 40, 50)
		for i = 1, #ROWS do
			local r = ROWS[i]
			if r.kind == "slider" then sliderRow(r) else choiceRow(r) end
			UiTranslate(0, ROW_H)
		end
		UiTranslate(PANEL_W / 2 - 40, 26)
		UiAlign("center middle")
		UiFont("regular.ttf", 22)
		UiColor(1, 1, 1, 1)
		UiButtonImageBox("ui/common/box-outline-6.png", 6, 6, 1, 1, 1, 0.8)
		UiPush()
			UiTranslate(-130, 0)
			if UiTextButton(tr({ "Reset to defaults", "Сбросить" }), 230, 44) then resetDefaults() end
		UiPop()
		UiPush()
			UiTranslate(130, 0)
			if UiTextButton(tr({ "Close", "Закрыть" }), 230, 44) then Menu() end
		UiPop()
	UiPop()
end
